const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=id=>document.getElementById(id),shell=$('gameShell');
let W=960,H=540,dpr=1,playing=false,ended=false,muted=false,audio=null,last=0,elapsed=0,left=120,score=0,lives=3,combo=0,aim=-.72,fireWait=0,spawnWait=.4,shake=0,toastWait=0,high=+(localStorage.getItem('belkoboomBest')||0);
let nuts=[],shots=[],particles=[],leaves=[],clouds=[];
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function resize(){const r=shell.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);W=960;H=960*r.height/r.width;ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);seedScene()}
function seedScene(){leaves=Array.from({length:34},()=>({x:rand(0,W),y:rand(0,H*.76),r:rand(18,76),h:rand(85,148),a:rand(.08,.2)}));clouds=Array.from({length:5},()=>({x:rand(0,W),y:rand(90,H*.46),s:rand(.55,1.3)}))}
window.addEventListener('resize',resize);resize();
function sound(type){if(muted)return;try{audio ||=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);const now=audio.currentTime;let f=type==='hit'?520:type==='fire'?190:type==='lose'?120:700;o.type=type==='hit'?'sine':'triangle';o.frequency.setValueAtTime(f,now);o.frequency.exponentialRampToValueAtTime(type==='fire'?85:f*1.65,now+.11);g.gain.setValueAtTime(.055,now);g.gain.exponentialRampToValueAtTime(.001,now+.13);o.start(now);o.stop(now+.14)}catch(e){}}
function updateHud(){ $('score').textContent=String(score).padStart(5,'0');$('timer').textContent=`${Math.floor(left/60)}:${String(Math.ceil(left%60)).padStart(2,'0')}`;$('lives').textContent='♥ '.repeat(lives).trim()||'—';}
function notify(text){const t=$('toast');t.textContent=text;t.classList.add('show');toastWait=.75}
function startGame(){nuts=[];shots=[];particles=[];score=0;lives=3;combo=0;elapsed=0;left=120;fireWait=.15;spawnWait=.35;shake=0;playing=true;ended=false;$('overlay').classList.add('hidden');$('hint').style.opacity='1';updateHud();last=performance.now();sound('start')}
function finish(win){playing=false;ended=true;high=Math.max(high,score);localStorage.setItem('belkoboomBest',high);$('overlayTitle').textContent=win?'ЛЕС СПАСЁН!':'ОРЕХОВЫЙ ПРОВАЛ';$('overlayText').textContent=win?`Две минуты выдержаны! Ты набрал ${score} очков и спас беличий дом.`:`Орехи прорвались! Твой счёт — ${score}. Попробуй продержаться дольше.`;$('startBtn').textContent='ЕЩЁ ОДИН РАУНД';$('bestNote').textContent=`Рекорд: ${String(high).padStart(5,'0')} · Сможешь побить?`;$('overlay').classList.remove('hidden');sound(win?'win':'lose')}
function fire(){if(!playing||fireWait>0)return;const x=W*.135,y=H*.79,speed=670;shots.push({x:x+Math.cos(aim)*39,y:y+Math.sin(aim)*39,vx:Math.cos(aim)*speed,vy:Math.sin(aim)*speed,r:17,spin:rand(-4,4)});fireWait=.3;shake=3;for(let i=0;i<5;i++)particles.push({x,y,vx:rand(-50,30),vy:rand(-80,15),life:rand(.18,.4),max:.4,color:'#ffc764',r:rand(2,5)});sound('fire')}
function spawnNut(){const big=Math.random()<Math.min(.3,.08+elapsed/280),gold=Math.random()<.105;const r=big?rand(24,30):rand(17,23);nuts.push({x:W+40,y:rand(H*.24,H*.69),baseY:0,r,vx:-rand(165,250)*(1+elapsed/105),phase:rand(0,7),amp:rand(18,55),freq:rand(1.7,3.8),age:0,hp:big?2:1,gold,spin:rand(-2.5,2.5),rot:rand(0,6.2),flash:0});nuts[nuts.length-1].baseY=nuts[nuts.length-1].y}
function burst(x,y,color,count=10){for(let i=0;i<count;i++){const a=rand(0,Math.PI*2),v=rand(50,240),life=rand(.24,.65);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life,max:life,color,r:rand(2,5)})}}
function tick(dt){if(!playing)return;elapsed+=dt;left=Math.max(0,120-elapsed);fireWait=Math.max(0,fireWait-dt);spawnWait-=dt;shake=Math.max(0,shake-dt*18);toastWait-=dt;if(toastWait<=0)$('toast').classList.remove('show');if(spawnWait<=0){spawnNut();spawnWait=Math.max(.43,1.05-elapsed*.004)+rand(-.16,.22)}if(elapsed>0&&Math.floor(elapsed)%10===0&&Math.floor(elapsed-dt)!==Math.floor(elapsed))notify('ОРЕХИ УСКОРЯЮТСЯ!');
 for(const n of nuts){n.age+=dt;n.x+=n.vx*dt;n.y=n.baseY+Math.sin(n.age*n.freq+n.phase)*n.amp;n.rot+=n.spin*dt;n.flash=Math.max(0,n.flash-dt);if(n.x<W*.11){n.gone=true;lives--;combo=0;shake=8;burst(W*.12,n.y,'#ff8366',9);sound('lose');if(lives<=0){updateHud();finish(false);return}}}
 for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.vy+=410*dt;s.rot=(s.rot||0)+s.spin*dt;if(s.y>H+30||s.x>W+30||s.x<0)s.gone=true;for(const n of nuts){if(n.gone)continue;const dx=s.x-n.x,dy=s.y-n.y;if(dx*dx+dy*dy<(n.r+s.r-3)**2){s.gone=true;n.hp--;n.flash=.12;burst(s.x,s.y,n.gold?'#ffe277':'#e7b553',7);if(n.hp<=0){n.gone=true;combo++;const pts=(n.gold?300:100)*(1+Math.floor(combo/5)*.25);score+=pts;burst(n.x,n.y,n.gold?'#fff08c':'#d99a51',n.gold?19:13);notify(n.gold?'ЗОЛОТОЙ ОРЕХ!':combo>1?`ПОПАДАНИЕ ×${combo}`:'ПОПАЛ!');sound('hit')}else sound('hit');break}}}
 nuts=nuts.filter(n=>!n.gone);shots=shots.filter(s=>!s.gone);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=180*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);if(Math.floor(elapsed)!==Math.floor(elapsed-dt))updateHud();if(left<=0){updateHud();finish(true)}}

function roundedRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
function drawNut(c,x,y,r,rot,gold=false,flash=0){c.save();c.translate(x,y);c.rotate(rot);const shell=gold?'#ffd35a':'#a96832',shade=gold?'#a95d26':'#59371f';c.fillStyle=shade;c.beginPath();c.ellipse(0,2,r*.76,r*.91,0,0,Math.PI*2);c.fill();c.fillStyle=flash?'#fff0b0':shell;c.beginPath();c.moveTo(-r*.64,-r*.2);c.quadraticCurveTo(-r*.52,-r*.82,0,-r*.94);c.quadraticCurveTo(r*.54,-r*.79,r*.66,-r*.15);c.quadraticCurveTo(r*.72,r*.5,0,r*.91);c.quadraticCurveTo(-r*.72,r*.56,-r*.64,-r*.2);c.fill();c.fillStyle=gold?'#ffeb9d':'#d99a55';c.beginPath();c.ellipse(0,-r*.63,r*.48,r*.18,0,Math.PI,0);c.fill();c.strokeStyle=gold?'#fff1a7':'#61391f';c.lineWidth=Math.max(2,r*.12);c.beginPath();c.moveTo(-r*.42,-r*.21);c.quadraticCurveTo(0,-r*.43,r*.4,-r*.2);c.stroke();if(gold){c.fillStyle='#fff5bd';c.beginPath();c.arc(-r*.26,-r*.46,r*.095,0,Math.PI*2);c.fill()}c.restore()}
function drawSquirrel(c,x,y,scale,rot=0,mini=false){c.save();c.translate(x,y);c.rotate(rot);c.scale(scale,scale);c.lineCap='round';c.lineJoin='round';// curled tail
 c.fillStyle='#a9532d';c.strokeStyle='#71391f';c.lineWidth=3;c.beginPath();c.moveTo(-11,5);c.bezierCurveTo(-33,0,-31,-28,-14,-32);c.bezierCurveTo(2,-37,9,-18,-4,-15);c.bezierCurveTo(-15,-12,-12,-24,-5,-25);c.bezierCurveTo(-18,-28,-25,-14,-18,-6);c.quadraticCurveTo(-13,0,-5,0);c.closePath();c.fill();c.stroke();
 c.fillStyle='#bc6034';c.beginPath();c.ellipse(0,0,13,16,-.25,0,Math.PI*2);c.fill();c.stroke();c.fillStyle='#f6d4a0';c.beginPath();c.ellipse(3,5,8,9,-.15,0,Math.PI*2);c.fill();
 c.fillStyle='#bd6137';c.beginPath();c.arc(10,-12,11,0,Math.PI*2);c.fill();c.stroke();c.beginPath();c.moveTo(2,-19);c.lineTo(3,-30);c.lineTo(12,-21);c.closePath();c.fill();c.stroke();c.fillStyle='#edaa81';c.beginPath();c.moveTo(5,-21);c.lineTo(5,-26);c.lineTo(9,-21);c.closePath();c.fill();
 c.fillStyle='#fff4d8';c.beginPath();c.ellipse(14,-13,4,5,0,0,Math.PI*2);c.fill();c.fillStyle='#2d211b';c.beginPath();c.arc(15,-13,1.8,0,Math.PI*2);c.fill();c.fillStyle='#e99a83';c.beginPath();c.arc(21,-10,2.4,0,Math.PI*2);c.fill();
 c.strokeStyle='#f2d5a5';c.lineWidth=2.2;c.beginPath();c.moveTo(7,11);c.lineTo(14,12);c.moveTo(-2,12);c.lineTo(-7,13);c.stroke();if(!mini){c.fillStyle='#f2b74e';c.beginPath();c.arc(0,-1,3.7,0,Math.PI*2);c.fill()}c.restore()}
function drawCannon(x,y){ctx.save();ctx.translate(x,y);ctx.rotate(aim);ctx.fillStyle='#48291e';ctx.beginPath();ctx.roundRect(-3,-13,74,26,10);ctx.fill();ctx.fillStyle='#8c4c2b';ctx.beginPath();ctx.roundRect(2,-11,60,19,8);ctx.fill();ctx.fillStyle='#c98542';ctx.beginPath();ctx.roundRect(51,-14,18,28,5);ctx.fill();ctx.fillStyle='#5b3826';ctx.beginPath();ctx.ellipse(68,0,5,9,0,0,Math.PI*2);ctx.fill();ctx.restore();ctx.fillStyle='#704323';ctx.beginPath();ctx.ellipse(x,y+14,31,9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bd7942';for(const dx of [-17,17]){ctx.beginPath();ctx.arc(x+dx,y+13,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#573723';ctx.beginPath();ctx.arc(x+dx,y+13,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#bd7942'}drawSquirrel(ctx,x-21,y-20,1.22,-.12,false)}
function drawBackground(t){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#83bd91');g.addColorStop(.52,'#b3d48f');g.addColorStop(.521,'#7ba75c');g.addColorStop(1,'#476b3b');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // soft sky sun and distant hills
 const sun=ctx.createRadialGradient(W*.73,H*.2,5,W*.73,H*.2,H*.34);sun.addColorStop(0,'#fff2b677');sun.addColorStop(1,'#fff2b600');ctx.fillStyle=sun;ctx.fillRect(0,0,W,H*.65);
 ctx.fillStyle='#8cb878';ctx.beginPath();ctx.moveTo(0,H*.57);ctx.quadraticCurveTo(W*.22,H*.42,W*.43,H*.58);ctx.quadraticCurveTo(W*.68,H*.4,W,H*.56);ctx.lineTo(W,H*.83);ctx.lineTo(0,H*.83);ctx.fill();
 for(const cl of clouds){const x=(cl.x-t*5*cl.s+W)%W;ctx.fillStyle='#fff8dc28';ctx.beginPath();ctx.ellipse(x,cl.y,43*cl.s,10*cl.s,0,0,Math.PI*2);ctx.ellipse(x-19*cl.s,cl.y-5*cl.s,21*cl.s,12*cl.s,0,0,Math.PI*2);ctx.ellipse(x+15*cl.s,cl.y-7*cl.s,24*cl.s,14*cl.s,0,0,Math.PI*2);ctx.fill()}
 // trees, leafy canopy
 for(const l of leaves){ctx.fillStyle=`hsla(${l.h},34%,${27+l.r*.08}%,${l.a})`;ctx.beginPath();ctx.arc(l.x,l.y,l.r,0,Math.PI*2);ctx.fill()}
 // far little trees
 for(let i=0;i<12;i++){const x=((i*103+17-t*8)% (W+130)+W+130)%(W+130)-30,y=H*.65+(i%3)*H*.025,s=.45+(i%4)*.12;ctx.fillStyle='#5b804d';ctx.fillRect(x-4*s,y,8*s,H*.14);ctx.fillStyle=i%2?'#689260':'#5f8957';ctx.beginPath();ctx.arc(x,y-8*s,24*s,0,Math.PI*2);ctx.arc(x-15*s,y+2*s,17*s,0,Math.PI*2);ctx.arc(x+16*s,y+3*s,17*s,0,Math.PI*2);ctx.fill()}
 // cabin near finish line
 const hx=W*.88,hy=H*.64;ctx.fillStyle='#865439';ctx.fillRect(hx,hy,76,55);ctx.fillStyle='#68412b';ctx.beginPath();ctx.moveTo(hx-9,hy+3);ctx.lineTo(hx+38,hy-29);ctx.lineTo(hx+85,hy+3);ctx.closePath();ctx.fill();ctx.fillStyle='#f5cb6f';ctx.fillRect(hx+11,hy+17,15,17);ctx.fillRect(hx+49,hy+17,15,17);ctx.fillStyle='#463124';ctx.fillRect(hx+32,hy+29,15,26);
 // ground
 ctx.fillStyle='#41643c';ctx.fillRect(0,H*.79,W,H*.21);ctx.fillStyle='#6f914d';ctx.beginPath();ctx.moveTo(0,H*.79);for(let x=0;x<=W;x+=30)ctx.lineTo(x,H*.79+Math.sin(x*.022+t*.6)*4);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();
 for(let i=0;i<32;i++){const x=(i*41-t*24+W*3)%(W),y=H*.82+(i%5)*H*.034;ctx.strokeStyle=i%2?'#a8c46a':'#c2cf77';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y+6);ctx.quadraticCurveTo(x-3,y,x+((i%3)-1)*5,y-7);ctx.stroke()}
 // danger line at home
 ctx.strokeStyle='#f5d17b55';ctx.setLineDash([6,8]);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(W*.105,H*.48);ctx.lineTo(W*.105,H*.79);ctx.stroke();ctx.setLineDash([])
}

function drawTrajectory(){const sx=W*.135+Math.cos(aim)*71,sy=H*.79-20+Math.sin(aim)*71;ctx.fillStyle='#ffeab477';for(let t=.12;t<.9;t+=.13){const x=sx+Math.cos(aim)*670*t,y=sy+Math.sin(aim)*670*t+205*t*t;if(y<H*.79&&x<W*.83){ctx.beginPath();ctx.arc(x,y,2.1,0,Math.PI*2);ctx.fill()}}}
function render(now){const t=now/1000;ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawBackground(t);if(playing)drawTrajectory();
 // acorn targets
 for(const n of nuts)drawNut(ctx,n.x,n.y,n.r,n.rot,n.gold,n.flash);
 // launching squirrels
 for(const s of shots){const angle=Math.atan2(s.vy,s.vx);drawSquirrel(ctx,s.x,s.y,.92,angle,true);}
 // impact sparks
 for(const p of particles){ctx.globalAlpha=clamp(p.life/(p.max*.45),0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r*(.5+.5*p.life/p.max),0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 drawCannon(W*.135,H*.79);
 if(playing){const rect=canvas.getBoundingClientRect(),mx=(pointer.x-rect.left)*W/rect.width,my=(pointer.y-rect.top)*H/rect.height;ctx.strokeStyle='#fff4d8c9';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(mx,my,8,0,Math.PI*2);ctx.moveTo(mx-13,my);ctx.lineTo(mx-5,my);ctx.moveTo(mx+5,my);ctx.lineTo(mx+13,my);ctx.moveTo(mx,my-13);ctx.lineTo(mx,my-5);ctx.moveTo(mx,my+5);ctx.lineTo(mx,my+13);ctx.stroke()}
 ctx.restore();}
let pointer={x:canvas.clientWidth*.55,y:canvas.clientHeight*.35};function pointerAim(e){const r=canvas.getBoundingClientRect();pointer.x=e.clientX;pointer.y=e.clientY;const px=(e.clientX-r.left)*W/r.width,py=(e.clientY-r.top)*H/r.height;aim=clamp(Math.atan2(py-H*.79,px-W*.135),-1.48,.24)}
canvas.addEventListener('pointermove',pointerAim);canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')e.preventDefault();pointerAim(e);fire()});$('mobileFire').addEventListener('pointerdown',e=>{e.preventDefault();fire()});
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'){fire();if(!playing&&!ended)startGame()}if(e.code==='KeyR'){startGame()}if(e.code==='ArrowUp')aim=clamp(aim-.07,-1.48,.24);if(e.code==='ArrowDown')aim=clamp(aim+.07,-1.48,.24);if(e.code==='ArrowLeft')aim=clamp(aim-.07,-1.48,.24);if(e.code==='ArrowRight')aim=clamp(aim+.07,-1.48,.24)});
$('startBtn').addEventListener('click',startGame);$('sound').addEventListener('click',()=>{muted=!muted;$('sound').textContent=muted?'♫̸':'♫';$('sound').setAttribute('aria-label',muted?'Звук выключен':'Звук включен');if(!muted)sound('hit')});
function frame(now){const dt=Math.min(.035,(now-last)/1000||0);last=now;tick(dt);render(now);requestAnimationFrame(frame)}requestAnimationFrame(frame);updateHud();$('bestNote').textContent=`Рекорд: ${String(high).padStart(5,'0')} · Быстро целься: орехи становятся всё злее!`;
</script>
</body>
</html>

